 }

 pub(super) fn set_blocked(&mut self, id: &str, blocked: bool) -> io::Result<()> {
     if !valid_id(id) {
         return Err(invalid());
     }
     let mut next = self.snapshot.clone();
     match next
         .blocked_accounts
         .binary_search_by(|entry| entry.as_str().cmp(id))
     {
         Ok(index) if !blocked => {
