         }
         Err(_) if blocked && next.blocked_accounts.len() >= 1024 => return Err(invalid()),
         Err(index) if blocked => next.blocked_accounts.insert(index, id.into()),
         _ => return Ok(()),
     }
     self.commit(next)
 }

