    // it and bind `from` to the cryptographically-authenticated Noise peer (Alice).
    let spoofed = "f".repeat(32);
    let payload = format!(r#"{{"kind":"offer","sdp":"v=0","from":"{spoofed}"}}"#);
    alice_node
        .send_call_signal(&bob_uid, payload.as_bytes())
